$chromeDevtoolsDestCursor = Join-Path $chromeDevtoolsDirCursor "SKILL.md"
[System.IO.File]::WriteAllText($chromeDevtoolsDestCursor, $chromeDevtoolsSkill, [System.Text.UTF8Encoding]::new($false))
